<div x-data="historyIndex()" x-init="load()" x-cloak>
    <div class="mb-7"><p class="text-sm text-slate-600">Catatan perubahan status aset</p><h2 class="mt-1 text-2xl font-semibold tracking-tight text-navy-900 sm:text-3xl">Histori perubahan</h2></div>
    <section class="rounded-2xl border border-border bg-white p-4 shadow-sm"><div class="grid gap-3 md:grid-cols-3"><div><label class="field-label" for="history-search">Cari kode aset</label><input id="history-search" x-model="search" type="search" class="field-input"></div><div><label class="field-label" for="history-type">Jenis aset</label><select id="history-type" x-model="filters.type" class="field-input"><option value="">Semua jenis</option><option value="lpju">LPJU</option><option value="rambu">Rambu</option></select></div><div><label class="field-label" for="history-status">Status baru</label><select id="history-status" x-model="filters.status" class="field-input"><option value="">Semua status</option><option value="baik">Baik</option><option value="rusak">Rusak</option><option value="perbaikan">Perbaikan</option></select></div></div></section>
    <div x-show="error" class="mt-5 rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700"><span x-text="error"></span> <button @click="load()" class="font-semibold underline">Coba lagi</button></div>
    <section class="mt-5 overflow-hidden rounded-2xl border border-border bg-white shadow-sm"><div class="border-b border-border px-5 py-4"><h3 class="font-semibold text-navy-900">Daftar perubahan</h3><p class="mt-1 text-xs text-slate-500" x-text="loading ? 'Memuat...' : `${filtered.length} perubahan`"></p></div><div class="overflow-x-auto"><table class="w-full min-w-[850px] text-left text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-wider text-slate-500"><tr><th class="px-5 py-3">Aset</th><th class="px-5 py-3">Perubahan status</th><th class="px-5 py-3">Keterangan</th><th class="px-5 py-3">Pengubah</th><th class="px-5 py-3">Tanggal</th></tr></thead><tbody class="divide-y divide-border"><template x-for="item in filtered" :key="item.id"><tr><td class="px-5 py-4"><p class="font-semibold text-navy-900" x-text="code(item)"></p><p class="text-xs text-slate-500" x-text="type(item)"></p></td><td class="px-5 py-4"><span x-text="`${item.status_lama || '-'} → ${item.status_baru}`"></span></td><td class="px-5 py-4 text-slate-600" x-text="item.keterangan || '-' "></td><td class="px-5 py-4 text-slate-600" x-text="item.pengubah?.name || '-' "></td><td class="px-5 py-4 text-slate-600" x-text="formatDate(item.tanggal || item.created_at)"></td></tr></template></tbody></table></div><div x-show="!loading && !error && !filtered.length" class="px-5 py-16 text-center text-sm text-slate-500">Belum ada histori perubahan.</div></section>
</div>
<script>function historyIndex(){return{items:[],loading:true,error:'',search:'',filters:{type:'',status:''},get filtered(){const q=this.search.toLowerCase().trim();return this.items.filter(x=>(!q||this.code(x).toLowerCase().includes(q))&&(!this.filters.type||this.type(x).toLowerCase()===this.filters.type)&&(!this.filters.status||x.status_baru===this.filters.status))},async load(){this.loading=true;this.error='';try{const r=await window.axios.get('/api/histori');const body=r.data;this.items=(Array.isArray(body)?body:(body?.data||[])).sort((a,b)=>new Date(b.tanggal||b.created_at)-new Date(a.tanggal||a.created_at))}catch(e){this.error=e.response?.status===401?'Sesi login tidak ditemukan.':e.response?.data?.message||'Gagal memuat histori.'}finally{this.loading=false}},type(x){return String(x.aset_type||'').toLowerCase().includes('rambu')?'rambu':'lpju'},code(x){return `${this.type(x).toUpperCase()}-${String(x.aset_id).padStart(4,'0')}`},formatDate(x){return x?new Date(x).toLocaleDateString('id-ID',{day:'2-digit',month:'short',year:'numeric'}):'-'}}}</script>
@endsection
